@Composable private fun StateMessage(title:String,button:String?=null,onClick:()->Unit={}){Column(Modifier.fillMaxWidth().padding(32.dp)){Text(title,style=MaterialTheme.typography.bodyLarge);button?.let{Button(onClick){Text(it)}}}}
private fun displayDate(value:String?):String?=try{value?.let{LocalDate.parse(it).format(DateTimeFormatter.ofPattern("d MMMM yyyy"))}}catch(_:Exception){value}
@Composable fun TenderCardView(t:Tender,onClick:()->Unit){Card(Modifier.fillMaxWidth().padding(vertical=6.dp).clickable(onClick=onClick)){Column(Modifier.padding(16.dp)){Text(t.title,style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.SemiBold);Spacer(Modifier.height(5.dp));Text(t.organisation);Text(listOfNotNull(t.province,t.municipality).joinToString(" / "));Spacer(Modifier.height(10.dp));Text(if(t.closing_date==null)"Closing date not provided" else "Closing: ${displayDate(t.closing_date)}${t.closing_time?.let{" at ${it.take(5)}"}?:""}",style=MaterialTheme.typography.titleSmall,color=if(t.status=="OPEN")MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error,fontWeight=FontWeight.Bold);t.category?.let{Text("Category: $it")};t.reference_number?.let{Text("Reference: $it")};if(t.status!="OPEN")Text(t.status,color=MaterialTheme.colorScheme.error,fontWeight=FontWeight.Bold)}}}
@Composable fun HomeDataScreen(state:DataState<HomeResponse>,onRetry:()->Unit,onTender:(String)->Unit){when(state){DataState.Loading->StateMessage("Loading current tenders…");DataState.Empty->StateMessage("No current tenders are available.","Retry",onRetry);is DataState.Error->StateMessage(state.message,"Retry",onRetry);is DataState.Success->LazyColumn(Modifier.fillMaxSize().padding(16.dp)){item{Text("Latest tenders",style=MaterialTheme.typography.headlineMedium)};items(state.data.latest,key={"latest-${it.id}"}){TenderCardView(it){onTender(it.id)}};item{Text("Closing soon",style=MaterialTheme.typography.headlineMedium,modifier=Modifier.padding(top=20.dp))};items(state.data.closing_soon,key={"closing-${it.id}"}){TenderCardView(it){onTender(it.id)}};item{Text("Recently added",style=MaterialTheme.typography.headlineMedium,modifier=Modifier.padding(top=20.dp))};items(state.data.recently_added,key={"recent-${it.id}"}){TenderCardView(it){onTender(it.id)}}}}}
@OptIn(ExperimentalMaterial3Api::class)
@Composable fun SearchDataScreen(state:DataState<SearchResults>,filters:TenderFilters,geography:GeographyOptions,onSearch:(String,TenderFilters,String)->Unit,onRetry:()->Unit,onLoadMore:()->Unit,onTender:(String)->Unit){var query by remember{mutableStateOf("")};var sort by remember{mutableStateOf("relevance")};var showFilters by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize().padding(16.dp)){Text("Search tenders",style=MaterialTheme.typography.headlineMedium);OutlinedTextField(query,{query=it},label={Text("Keywords")},singleLine=true,modifier=Modifier.fillMaxWidth());Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){OutlinedButton({showFilters=true}){Text("Filters${filters.activeCount().takeIf{it>0}?.let{" ($it)"}?:""}")};TextButton({sort=when(sort){"relevance"->"newest";"newest"->"closing_soon";else->"relevance"}}){Text("Sort: ${sort.replace('_',' ')}")}};Button({onSearch(query,filters,sort)},Modifier.fillMaxWidth()){Text("Search")};Box(Modifier.weight(1f)){when(state){DataState.Loading->StateMessage("Searching tenders…");DataState.Empty->StateMessage("No tenders match your search.");is DataState.Error->StateMessage(state.message,"Retry",onRetry);is DataState.Success->LazyColumn{items(state.data.items,key={it.id}){TenderCardView(it){onTender(it.id)}};if(state.data.page<state.data.totalPages)item{Button(onLoadMore,enabled=!state.data.loadingMore,modifier=Modifier.fillMaxWidth()){Text(if(state.data.loadingMore)"Loading…" else "Load more")}}}}}}
 if(showFilters)FilterSheet(filters,geography,onDismiss={showFilters=false}){showFilters=false;onSearch(query,it,sort)}}
