@Composable private fun FilterSheet(current:TenderFilters,geo:GeographyOptions,onDismiss:()->Unit,onApply:(TenderFilters)->Unit){var draft by remember(current){mutableStateOf(current)};val districts=geo.districts.filter{draft.provinceId==null||it.province_id==draft.provinceId};val municipalities=geo.municipalities.filter{(draft.provinceId==null||it.province_id==draft.provinceId)&&(draft.districtId==null||it.district_id==draft.districtId)};ModalBottomSheet(onDismissRequest=onDismiss){LazyColumn(Modifier.fillMaxWidth().padding(horizontal=20.dp),contentPadding=PaddingValues(bottom=32.dp)){item{Text("Search filters",style=MaterialTheme.typography.headlineSmall);DropdownField("Province",geo.provinces,draft.provinceId,{it.id},{it.name}){draft=draft.copy(provinceId=it,districtId=null,municipalityId=null)};DropdownField("District",districts,draft.districtId,{it.id},{it.name}){draft=draft.copy(districtId=it,municipalityId=null)};DropdownField("Municipality",municipalities,draft.municipalityId,{it.id},{it.name}){draft=draft.copy(municipalityId=it)};FilterText("Category",draft.category){draft=draft.copy(category=it)};FilterText("Tender type",draft.tenderType){draft=draft.copy(tenderType=it)};FilterText("Closing from (YYYY-MM-DD)",draft.closingFrom){draft=draft.copy(closingFrom=it)};FilterText("Closing to (YYYY-MM-DD)",draft.closingTo){draft=draft.copy(closingTo=it)};FilterText("Issue from (YYYY-MM-DD)",draft.issueFrom){draft=draft.copy(issueFrom=it)};FilterText("Issue to (YYYY-MM-DD)",draft.issueTo){draft=draft.copy(issueTo=it)};FilterText("Minimum value",draft.minValue){draft=draft.copy(minValue=it)};FilterText("Maximum value",draft.maxValue){draft=draft.copy(maxValue=it)};DropdownField("Status",listOf("OPEN","CLOSED","CANCELLED","UPCOMING"),draft.status.ifBlank{null},{it},{it}){draft=draft.copy(status=it?:"")};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){TextButton({draft=TenderFilters()}){Text("Clear")};Button({onApply(draft)}){Text("Apply filters")}}}}}}
@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun <T> DropdownField(label:String,items:List<T>,selected:String?,id:(T)->String,name:(T)->String,onSelect:(String?)->Unit){var expanded by remember{mutableStateOf(false)};val display=items.firstOrNull{id(it)==selected}?.let(name)?:"Any";ExposedDropdownMenuBox(expanded,{expanded=it}){OutlinedTextField(display,{},readOnly=true,label={Text(label)},trailingIcon={ExposedDropdownMenuDefaults.TrailingIcon(expanded)},modifier=Modifier.menuAnchor().fillMaxWidth());ExposedDropdownMenu(expanded,{expanded=false}){DropdownMenuItem({Text("Any")},{onSelect(null);expanded=false});items.forEach{item->DropdownMenuItem({Text(name(item))},{onSelect(id(item));expanded=false})}}}}
@Composable private fun FilterText(label:String,value:String,onValue:(String)->Unit){OutlinedTextField(value,onValue,label={Text(label)},singleLine=true,modifier=Modifier.fillMaxWidth())}
@Composable fun TenderDetailScreen(state:DataState<TenderDetail>,onRetry:()->Unit){val uri=LocalUriHandler.current;when(state){DataState.Loading->StateMessage("Loading tender details…");DataState.Empty->StateMessage("Tender not found.");is DataState.Error->StateMessage(state.message,"Retry",onRetry);is DataState.Success->{val t=state.data;LazyColumn(Modifier.fillMaxSize().padding(20.dp)){item{Text(t.title,style=MaterialTheme.typography.headlineMedium);Text(t.organisation,style=MaterialTheme.typography.titleMedium);Section("TenderHub normalized information");Field("Reference",t.reference_number);Field("Province",t.province);Field("Municipality",t.municipality);Field("District",t.district);Field("Category",t.category);Field("Tender type",t.tender_type);Field("Issue date",displayDate(t.issue_date));Field("Closing",if(t.closing_date==null)"Closing date not provided" else "${displayDate(t.closing_date)}${t.closing_time?.let{" at ${it.take(5)}"}?:""}");Field("Status",t.status);Field("Estimated value",t.estimated_value?.let{"${t.currency} ${"%,.2f".format(it)}"});Field("Description",t.description);Field("Contact",listOfNotNull(t.contact_name,t.contact_email,t.contact_phone).joinToString(" • ").ifBlank{null});Section("Source information");Text("TenderHub SA is not the issuing authority.");Field("Publisher",t.source.name);Field("Source reference",t.source_reference);Field("Ingested",t.ingested_at);Button({uri.openUri(t.source_url)}){Text("View Original Source")};Section("Documents");if(t.documents.isEmpty())Text("No source documents supplied") else t.documents.forEach{TextButton({uri.openUri(it.source_url)}){Text(it.name)}};Section("AI Analysis");Text("NOT IMPLEMENTED")}}}}}
@Composable private fun Section(value:String){Text(value,style=MaterialTheme.typography.titleLarge,modifier=Modifier.padding(top=24.dp,bottom=8.dp))}
@Composable private fun Field(label:String,value:String?){if(!value.isNullOrBlank()){Text(label,style=MaterialTheme.typography.labelMedium);Text(value,modifier=Modifier.padding(bottom=8.dp))}}
